private Aspose.Words.Document LoadWordTemplate()
{
    string strFilePath = Server.MapPath("~") + "\\Template\\MauWord\\" + GetTemplateFileName();
    if (!File.Exists(strFilePath))
    {
        MsgBox.ShowError("Không tìm thấy file mẫu Word: " + strFilePath);
        return null;
    }
    Aspose.Words.LoadOptions options = new Aspose.Words.LoadOptions();
    options.LoadFormat = Aspose.Words.LoadFormat.Doc;
    return new Aspose.Words.Document(strFilePath, options);
}
