using System;
using System.Diagnostics;
using System.IO;
using Aspose.Words;
class Bench
{
    static int Main(string[] args)
    {
        string templatePath = args[0];
        int count = int.Parse(args[1]);
        string root = args[2];
        string soffice = args.Length > 3 ? args[3] : "";
        string[] names = new string[]
        {
            "StudentID", "StudentCode", "StudentFirstName", "StudentLastName", "FullName",
            "BirthDateText", "ClassName", "CourseID", "SpecialBranchName", "SpecialBranchShortName",
            "PersonId", "PersonIdDate", "PersonIdPlace", "BirthPlace", "LiveAddress", "Tel",
            "DAY", "MONTH", "YEAR",
            "HD_FinishAt_DAY", "HD_FinishAt_MONTH", "HD_FinishAt_YEAR",
            "SoHD_1", "SoHD_2", "HD_StartAt", "HD_FinishAt", "HD_Price", "HD_Price_Text"
        };
        object[] values = new object[]
        {
            "1001", "SV001", "Nguyen Van", "An", "Nguyen Van An",
            "01/01/2000", "Lop A1", "K21", "Lai xe", "A1",
            "079123456789", "01/01/2018", "Gia Lai", "Gia Lai", "01A Duong 17/3", "0900000000",
            "28", "9", "2026",
            "28", "3", "2027",
            "001", "002", "28/09/2026", "28/03/2027", "8.000.000", "tam trieu dong"
        };
        string dirV1 = Path.Combine(root, "v1");
        string dirV3 = Path.Combine(root, "v3");
        if (Directory.Exists(root))
            Directory.Delete(root, true);
        Directory.CreateDirectory(dirV1);
        Directory.CreateDirectory(dirV3);
        LoadOptions warmOptions = new LoadOptions();
        warmOptions.LoadFormat = LoadFormat.Doc;
        Document warm = new Document(templatePath, warmOptions);
        warm.MailMerge.Execute(names, values);
        string warmPath = Path.Combine(root, "_warm.doc");
        warm.Save(warmPath, SaveFormat.Doc);
        File.Delete(warmPath);
        Stopwatch sw = Stopwatch.StartNew();
        int i;
        for (i = 0; i < count; i++)
        {
            LoadOptions options = new LoadOptions();
            options.LoadFormat = LoadFormat.Doc;
            Document document = new Document(templatePath, options);
            document.MailMerge.Execute(names, values);
            document.Save(Path.Combine(dirV1, "hd_" + i.ToString("000") + ".doc"), SaveFormat.Doc);
        }
        sw.Stop();
        Console.WriteLine("V1_ASPOSE_MS=" + sw.ElapsedMilliseconds.ToString());
        long sofficeMs = -1;
        int sofficeExit = -1;
        int pdfCount = 0;
        if (soffice.Length > 0 && File.Exists(soffice))
        {
            string profile = Path.Combine(root, "lo_profile");
            Directory.CreateDirectory(profile);
            string profileUri = "file:///" + profile.Replace("\\", "/");
            System.Text.StringBuilder cmd = new System.Text.StringBuilder();
            cmd.Append("-env:UserInstallation=" + profileUri + " --headless --norestore --convert-to pdf --outdir \"" + dirV1 + "\"");
            string[] docs = Directory.GetFiles(dirV1, "*.doc");
            int d;
            for (d = 0; d < docs.Length; d++)
                cmd.Append(" \"" + docs[d] + "\"");
            sw.Reset();
            sw.Start();
            Process p = new Process();
            p.StartInfo.FileName = soffice;
            p.StartInfo.Arguments = cmd.ToString();
            p.StartInfo.UseShellExecute = false;
            p.StartInfo.CreateNoWindow = true;
            p.Start();
            if (!p.WaitForExit(180000))
            {
                try { p.Kill(); } catch { }
                sofficeExit = -2;
            }
            else
                sofficeExit = p.ExitCode;
            sw.Stop();
            sofficeMs = sw.ElapsedMilliseconds;
            pdfCount = Directory.GetFiles(dirV1, "*.pdf").Length;
        }
        Console.WriteLine("V1_SOFFICE_MS=" + sofficeMs.ToString());
        Console.WriteLine("V1_SOFFICE_EXIT=" + sofficeExit.ToString());
        Console.WriteLine("V1_PDF_COUNT=" + pdfCount.ToString());
        sw.Reset();
        sw.Start();
        LoadOptions options3 = new LoadOptions();
        options3.LoadFormat = LoadFormat.Doc;
        Document template = new Document(templatePath, options3);
        for (i = 0; i < count; i++)
        {
            Document document = (Document)template.Clone();
            document.MailMerge.Execute(names, values);
            document.Save(Path.Combine(dirV3, "hd_" + i.ToString("000") + ".pdf"), SaveFormat.Pdf);
        }
        sw.Stop();
        Console.WriteLine("V3_ASPOSE_MS=" + sw.ElapsedMilliseconds.ToString());
        Console.WriteLine("V3_PDF_COUNT=" + Directory.GetFiles(dirV3, "*.pdf").Length.ToString());
        return 0;
    }
}

