function Clip($s) {
    if ($s -eq $null) { return "" }
    $t = ($s -replace "\s+", " ").Trim()
    if ($t.Length -gt 90) { return $t.Substring(0, 90) }
    return $t
}
try {
    $word = New-Object -ComObject Word.Application
    $word.Visible = $false
    $dir = Join-Path (Get-Location) "Template\MauWord"
    $files = Get-ChildItem -Path $dir -Filter "*.doc"
    foreach ($f in $files) {
        $doc = $word.Documents.Open($f.FullName, $false, $true)
        Write-Output ("FILE " + $f.Name)
        $sections = $doc.Sections.Count
        Write-Output ("  sections=" + $sections)
        for ($s = 1; $s -le $sections; $s++) {
            $sec = $doc.Sections.Item($s)
            $hdr = $sec.Headers.Item(1)
            $ftr = $sec.Footers.Item(1)
            Write-Output ("  sec" + $s + " headerTables=" + $hdr.Range.Tables.Count + " footerTables=" + $ftr.Range.Tables.Count + " headerShapes=" + $hdr.Shapes.Count)
        }
        $n = $doc.Tables.Count
        for ($i = 1; $i -le $n; $i++) {
            $t = $doc.Tables.Item($i)
            $cell = Clip $t.Cell(1, 1).Range.Text
            Write-Output ("  T" + $i + " " + $t.Rows.Count + "x" + $t.Columns.Count + " | " + $cell)
        }
        $ns = $doc.Shapes.Count
        for ($i = 1; $i -le $ns; $i++) {
            $sh = $doc.Shapes.Item($i)
            $tx = ""
            $tc = 0
            try {
                if ($sh.TextFrame.HasText -eq -1) { $tx = Clip $sh.TextFrame.TextRange.Text }
                $tc = $sh.TextFrame.TextRange.Tables.Count
            } catch {}
            Write-Output ("  S" + $i + " type=" + $sh.Type + " name=" + $sh.Name + " tablesInShape=" + $tc + " | " + $tx)
        }
        $doc.Close($false)
        $doc = $null
    }
}
finally {
    if ($doc -ne $null) { $doc.Close($false) }
    if ($word -ne $null) { $word.Quit() }
}

