using System;
using System.Collections;
using System.Data;
using System.IO;
using iTextSharp.text.pdf;
namespace InformationWeb.Controls.Report.HopDongPdf
{
    /// <summary>
    /// Mẫu 5 — điền ô AcroForm trên Mau5_HopDong_C1.pdf rồi khóa form.
    /// </summary>
    public static class HopDongMau5FormPdf
    {
        public static void Fill(string templatePath, string outputPath, DataRow row)
        {
            if (!File.Exists(templatePath))
                throw new FileNotFoundException("Không tìm thấy file mẫu PDF: " + templatePath);
            string strDir = Path.GetDirectoryName(outputPath);
            if (!string.IsNullOrEmpty(strDir) && !Directory.Exists(strDir))
                Directory.CreateDirectory(strDir);
            string soHd = GetString(row, "SoHD_1");
            string dayStart;
            string monthStart;
            string yearStart;
            string dayFinish;
            string monthFinish;
            string yearFinish;
            SplitDate(row, "HD_StartAt", out dayStart, out monthStart, out yearStart);
            SplitDate(row, "HD_FinishAt", out dayFinish, out monthFinish, out yearFinish);
            string priceText = FormatPrice(row);
            PdfReader reader = null;
            FileStream fs = null;
            PdfStamper stamper = null;
            try
            {
                reader = new PdfReader(templatePath);
                fs = new FileStream(outputPath, FileMode.Create, FileAccess.Write);
                stamper = new PdfStamper(reader, fs);
                AcroFields form = stamper.AcroFields;
                BaseFont fontRegular = CreateUnicodeFont(false);
                BaseFont fontItalic = CreateUnicodeFontItalic();
                form.AddSubstitutionFont(fontRegular);
                SetText(form, fontRegular, "SoHD_1_3", soHd);
                SetText(form, fontRegular, "SoHD_1_2", soHd);
                SetText(form, fontRegular, "SoHD_1", soHd);
                SetText(form, fontItalic, "DAY_2", dayStart);
                SetText(form, fontItalic, "MONTH_2", monthStart);
                SetText(form, fontItalic, "YEAR_2", yearStart);
                SetText(form, fontItalic, "HD_FinishAt_DAY", dayFinish);
                SetText(form, fontItalic, "HD_FinishAt_MONTH", monthFinish);
                SetText(form, fontItalic, "HD_FinishAt_YEAR", yearFinish);
                SetText(form, fontRegular, "FullName", GetString(row, "FullName"));
                SetText(form, fontRegular, "BirthDateText", GetString(row, "BirthDateText"));
                SetText(form, fontRegular, "LiveAddress", GetString(row, "LiveAddress"));
                SetText(form, fontRegular, "DAY", dayStart);
                SetText(form, fontRegular, "MONTH", monthStart);
                SetText(form, fontRegular, "YEAR", yearStart);
                SetText(form, fontRegular, "HD_Price_2", priceText);
                SetText(form, fontRegular, "HD_Price", priceText);
                stamper.FormFlattening = true;
            }
            finally
            {
                if (stamper != null)
                    stamper.Close();
                if (reader != null)
                    reader.Close();
                if (fs != null)
                    fs.Dispose();
            }
        }
        private static void SetText(AcroFields form, BaseFont font, string fieldName, string value)
        {
            string resolvedName = FindFieldName(form, fieldName);
            if (resolvedName == null)
                throw new InvalidOperationException("Không thấy ô trên PDF mẫu: " + fieldName);
            form.SetFieldProperty(resolvedName, "textfont", font, null);
            form.SetField(resolvedName, value == null ? "" : value);
        }
        private static string FindFieldName(AcroFields form, string fieldName)
        {
            foreach (object key in (IEnumerable)form.Fields.Keys)
            {
                string name = key.ToString();
                if (NormalizeName(name) == fieldName)
                    return name;
            }
            return null;
        }
        private static string NormalizeName(string name)
        {
            int i = 0;
            while (i < name.Length && !char.IsLetter(name[i]))
                i++;
            if (i == 0)
                return name;
            return name.Substring(i);
        }
        private static string GetString(DataRow row, string columnName)
        {
            if (row == null || row.Table == null || !row.Table.Columns.Contains(columnName))
                return "";
            if (row[columnName] == null || row[columnName] == DBNull.Value)
                return "";
            return row[columnName].ToString().Trim();
        }
        private static void SplitDate(DataRow row, string columnName, out string day, out string month, out string year)
        {
            day = "";
            month = "";
            year = "";
            string text = GetString(row, columnName);
            if (text == "")
                return;
            DateTime dtmValue;
            if (!DateTime.TryParse(text, out dtmValue))
                return;
            day = dtmValue.ToString("dd");
            month = dtmValue.Month.ToString();
            year = dtmValue.Year.ToString();
        }
        private static string FormatPrice(DataRow row)
        {
            decimal decPrice = 0;
            string text = GetString(row, "HD_Price");
            if (text != "")
                decPrice = Convert.ToDecimal(row["HD_Price"]);
            return decPrice.ToString("N0", System.Globalization.CultureInfo.InvariantCulture).Replace(",", ".");
        }
        private static BaseFont CreateUnicodeFont(bool bold)
        {
            string strFontFile = bold ? "timesbd.ttf" : "times.ttf";
            return CreateUnicodeFontFromFile(strFontFile);
        }
        private static BaseFont CreateUnicodeFontItalic()
        {
            string strFontPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Fonts), "timesi.ttf");
            if (File.Exists(strFontPath))
                return BaseFont.CreateFont(strFontPath, BaseFont.IDENTITY_H, BaseFont.EMBEDDED);
            return CreateUnicodeFont(false);
        }
        private static BaseFont CreateUnicodeFontFromFile(string strFontFile)
        {
            string strFontPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Fonts), strFontFile);
            if (!File.Exists(strFontPath))
                strFontPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Fonts), "arial.ttf");
            if (!File.Exists(strFontPath))
                return BaseFont.CreateFont(BaseFont.HELVETICA, BaseFont.CP1252, BaseFont.NOT_EMBEDDED);
            return BaseFont.CreateFont(strFontPath, BaseFont.IDENTITY_H, BaseFont.EMBEDDED);
        }
    }
}

